<?php /** @var array $submissions @var array $forms @var int $formId @var \Core\Security\Csrf $csrf @var string $basePath */ ?>
<div class="card"><div class="card-heading"><div><h2>Submission inbox</h2><p class="muted">Stored submissions remain available when a form is archived.</p></div><div class="button-row"><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/forms">Forms</a><a class="btn" href="<?= e_attr($basePath) ?>/admin/forms/export<?= $formId ? '?form=' . $formId : '' ?>">Export CSV</a></div></div>
<form method="get" action="<?= e_attr($basePath) ?>/admin/forms/submissions"><label>Filter by form</label><select name="form" onchange="this.form.submit()"><option value="0">All forms</option><?php foreach($forms as $form): ?><option value="<?= (int)$form['id'] ?>" <?= $formId===(int)$form['id']?'selected':'' ?>><?= e($form['name']) ?></option><?php endforeach; ?></select></form>
<?php if($submissions===[]): ?><p class="empty-state">No submissions.</p><?php else: ?><table><tr><th>Received</th><th>Form</th><th>Data</th><th>Status</th></tr><?php foreach($submissions as $entry): $data=json_decode((string)$entry['data_json'],true)?:[]; ?><tr><td><?= e($entry['created_at']) ?></td><td><?= e($entry['form_name']) ?></td><td><?php foreach($data as $label=>$value): ?><strong><?= e(ucwords(str_replace('_',' ',$label))) ?>:</strong> <?= nl2br(e((string)$value)) ?><br><?php endforeach; ?></td><td><span class="badge <?= $entry['status']==='new'?'warn':'ok' ?>"><?= e($entry['status']) ?></span><?php if($entry['status']==='new'): ?><form method="post" action="<?= e_attr($basePath) ?>/admin/forms/submissions/<?= (int)$entry['id'] ?>/read"><?= $csrf->field() ?><button class="btn small secondary">Mark read</button></form><?php endif; ?></td></tr><?php endforeach; ?></table><?php endif; ?>
</div>
